## Why This Is Asked
Tests interval DP, memoization, and bottom-up tabulation on a classic polygon triangulation problem with solution counting. It checks careful state design and combinatorial counting under optimal substructure.

## Key Concepts
- Interval DP on polygons: dp[i][j] = min over i<k<j of dp[i][k] + dp[k][j] + w[i]*w[k]*w[j]
- Counting optimal solutions: parallel cnt[i][j] updated when a new min is found or matched
- Circular handling: fix a root vertex and solve a linearized version

## Code Example
```javascript
function minTriangulation(w){
  const n = w.length;
  const dp = Array.from({length:n},()=>Array(n).fill(Infinity));
  const cnt = Array.from({length:n},()=>Array(n).fill(0));
  for(let i=0;i<n-1;i++){ dp[i][i+1] = 0; cnt[i][i+1] = 1; }
  for(let len=2; len<n; len++){
    for(let i=0; i+len<n; i++){
      const j = i+len;
      for(let k=i+1; k<j; k++){
        const val = dp[i][k] + dp[k][j] + w[i]*w[k]*w[j];
        if(val < dp[i][j]){ dp[i][j] = val; cnt[i][j] = cnt[i][k] * cnt[k][j]; }
        else if(val === dp[i][j]){ cnt[i][j] += cnt[i][k] * cnt[k][j]; }
      }
    }
  }
  return {minCost: dp[0][n-1], ways: cnt[0][n-1]};
}
```

## Why This Is Asked

This problem tests advanced dynamic programming: partitioning with a non-trivial segment cost that depends on min and max, requiring careful state design and in-loop maintenance of subproblem results. It also validates producing both memoized and iterative solutions and analyzing time/space trade-offs.

## Key Concepts

- DP with partition states
- In-loop maintenance of running min and max
- Top-down memoization vs bottom-up tabulation
- Time complexity: O(D*N^2); Space: O(D*N)

## Code Example

```javascript
// Top-down memoized
function minCost(A, D){
  const N = A.length;
  const memo = Array.from({length:D+1}, ()=> Array(N).fill(null));
  function solve(d, i){
    if (d === 1){
      let mn = Infinity, mx = -Infinity;
      for (let k = 0; k <= i; k++){ mn = Math.min(mn, A[k]); mx = Math.max(mx, A[k]); }
      return mn * mx;
    }
    if (memo[d][i] != null) return memo[d][i];
    let mn = Infinity, mx = -Infinity; let best = Infinity;
    for (let j = i; j >= d-1; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      best = Math.min(best, solve(d-1, j-1) + mn*mx);
    }
    memo[d][i] = best; return best;
  }
  return solve(D, N-1);
}

// Bottom-up
function minCostBottom(A, D){
  const N = A.length, INF = 1e18;
  const dp = Array.from({length:D+1}, ()=> Array(N).fill(INF));
  // base: d = 1
  for (let i = 0; i < N; i++){
    let mn = A[i], mx = A[i];
    for (let j = i; j >= 0; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      if (j === 0) dp[1][i] = Math.min(dp[1][i], mn*mx);
    }
  }
  for (let d = 2; d <= D; d++){
    for (let i = d-1; i < N; i++){
      let mn = A[i], mx = A[i];
      for (let j = i; j >= d-1; j--){
        mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
        dp[d][i] = Math.min(dp[d][i], dp[d-1][j-1] + mn*mx);
      }
    }
  }
  return dp[D][N-1];
}
```

## Why This Is Asked
Tests understanding of a Trie, basic operations, and how to implement autocomplete with limited results.

## Key Concepts
- Trie nodes with children and isEnd
- DFS traversal for autocomplete
- Lexicographic ordering via alphabetical traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}

class Trie {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }
  search(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) return false;
      node = node.children.get(ch);
    }
    return node.isEnd;
  }
  startsWith(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children.has(ch)) return false;
      node = node.children.get(ch);
    }
    return true;
  }
  autocomplete(prefix, limit) {
    let node = this.root; const path = [];
    for (const ch of prefix) {
      if (!node.children.has(ch)) return [];
      node = node.children.get(ch);
      path.push(ch);
    }
    const results = [];
    function dfs(n, acc) {
      if (results.length >= limit) return;
      if (n.isEnd) results.push(prefix + acc.join(''));
      const keys = Array.from(n.children.keys()).sort();
      for (const c of keys) {
        acc.push(c);
        dfs(n.children.get(c), acc);
        acc.pop();
      }
    }
    dfs(node, []);
    return results;
  }
}
```

